etl.query:

SELECT getdate() AS inicio_carga;


	INSERT INTO d02BI_COMUN.dbo.ejecuciones_etl (etl, inicio_carga) 
	VALUES ('etl_auditoria.xml',?inicio_carga);

SELECT els.LogEntryId, substring(els.UserName,4,11) as DNI, c.Name as nombre_informe, c.path, els.Format as formatoArchivo, els.requestType, els.Status, els.TimeStart, els.TimeEnd, case when datepart([hour], [timeStart])=8 then 1 when datepart([hour], [timeStart])=9 then 2 when datepart([hour], [timeStart])=10 then 3 when datepart([hour], [timeStart])=11 then 4 when datepart([hour], [timeStart])=12 then 5 when datepart([hour], [timeStart])=13 then 6 when datepart([hour], [timeStart])=14 then 7 when datepart([hour], [timeStart])=15 then 8 when datepart([hour], [timeStart])=16 then 9 when datepart([hour], [timeStart])=17 then 10 when datepart([hour], [timeStart])=18 then 11 when datepart([hour], [timeStart])=19 then 12 when datepart([hour], [timeStart])=20 then 13 when datepart([hour], [timeStart])=21 then 14 when datepart([hour], [timeStart])=22 then 15 when datepart([hour], [timeStart])=23 then 16 when datepart([hour], [timeStart])=0 then 17 when datepart([hour], [timeStart])=1 then 18 when datepart([hour], [timeStart])=2 then 19 when datepart([hour], [timeStart])=3 then 20 when datepart([hour], [timeStart])=4 then 21 when datepart([hour], [timeStart])=5 then 22 when datepart([hour], [timeStart])=6 then 23 when datepart([hour], [timeStart])=7 then 24 else 0 end as n_horas, els.reportAction FROM ExecutionLogStorage els LEFT JOIN Catalog c on c.ItemID = els.ReportID WHERE els.Format = 'PBIX'
and (c.path not like '%Pruebas%' and c.path not like '%OLD%') and els.reportAction = 13 ORDER BY timeStart DESC
DELETE FROM aud_logs_reports WHERE logEntryId = ?logEntryId; INSERT INTO aud_logs_reports (logEntryId, DNI, nombre_informe, path, formatoArchivo, requestType, Status, timeStart, timeEnd, n_horas, reportAction) VALUES (?logEntryId, ?DNI, ?nombre_informe, ?path, ?formatoArchivo, ?requestType, ?Status,?timeStart, ?timeEnd, ?n_horas, ?reportAction);

SELECT els.ExecutionId as execid, els.LogEntryId, substring(els.UserName,4,11) as DNI, c.Name as nombre_informe, c.path, els.Format as formatoArchivo, els.requestType, els.Status, els.TimeStart, els.TimeEnd, case when datepart([hour], [timeStart])=8 then 1 when datepart([hour], [timeStart])=9 then 2 when datepart([hour], [timeStart])=10 then 3 when datepart([hour], [timeStart])=11 then 4 when datepart([hour], [timeStart])=12 then 5 when datepart([hour], [timeStart])=13 then 6 when datepart([hour], [timeStart])=14 then 7 when datepart([hour], [timeStart])=15 then 8 when datepart([hour], [timeStart])=16 then 9 when datepart([hour], [timeStart])=17 then 10 when datepart([hour], [timeStart])=18 then 11 when datepart([hour], [timeStart])=19 then 12 when datepart([hour], [timeStart])=20 then 13 when datepart([hour], [timeStart])=21 then 14 when datepart([hour], [timeStart])=22 then 15 when datepart([hour], [timeStart])=23 then 16 when datepart([hour], [timeStart])=0 then 17 when datepart([hour], [timeStart])=1 then 18 when datepart([hour], [timeStart])=2 then 19 when datepart([hour], [timeStart])=3 then 20 when datepart([hour], [timeStart])=4 then 21 when datepart([hour], [timeStart])=5 then 22 when datepart([hour], [timeStart])=6 then 23 when datepart([hour], [timeStart])=7 then 24 else 0 end as n_horas, els.reportAction FROM ExecutionLogStorage els LEFT JOIN Catalog c on c.ItemID = els.ReportID WHERE els.Format = 'DataModel' and (c.path not like '%Pruebas%' and c.path not like '%OLD%')
ORDER BY timeStart DESC
DELETE FROM aud_logs_cargas WHERE logEntryId = ?logEntryId; INSERT INTO aud_logs_cargas (ExecutionId, logEntryId, DNI, nombre_informe, path, formatoArchivo, requestType, Status, timeStart, timeEnd, n_horas, reportAction) VALUES (?execid, ?logEntryId, ?DNI, ?nombre_informe, ?path, ?formatoArchivo, ?requestType, ?Status,?timeStart, ?timeEnd, ?n_horas, ?reportAction);


SELECT getdate() as fecha_actual;



	UPDATE d02BI_COMUN.dbo.ejecuciones_etl  SET fin_carga=?fecha_actual
	WHERE etl='etl_auditoria.xml' and fin_carga is null
		and not exists (select * 
						FROM d02BI_COMUN.dbo.ejecuciones_etl e2
						WHERE e2.etl='etl_auditoria.xml' and e2.fin_carga is null and e2.inicio_carga>ejecuciones_etl.inicio_carga);
